namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // ───────────────────────────────────────────────
    // CalculateTotal — DataRow for inline constants
    // ───────────────────────────────────────────────

    [TestMethod]
    [DataRow(10.00, 1, 0.0, 10.00, DisplayName = "Single item, no tax")]
    [DataRow(10.00, 5, 0.0, 50.00, DisplayName = "Multiple items, no tax")]
    [DataRow(10.00, 1, 0.10, 11.00, DisplayName = "Single item, 10% tax")]
    [DataRow(25.50, 3, 0.08, 82.62, DisplayName = "Fractional price, 8% tax")]
    [DataRow(0.00, 10, 0.20, 0.00, DisplayName = "Zero unit price")]
    [DataRow(99.99, 0, 0.15, 0.00, DisplayName = "Zero quantity")]
    [DataRow(100.00, 2, 1.0, 400.00, DisplayName = "Maximum tax rate (100%)")]
    public void CalculateTotal_WithValidInputs_ReturnsExpectedTotal(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, result);
    }

    [TestMethod]
    [DataRow(-1.00, 1, 0.10, "unitPrice", DisplayName = "Negative unit price throws")]
    [DataRow(10.00, -1, 0.10, "quantity", DisplayName = "Negative quantity throws")]
    [DataRow(10.00, 1, -0.01, "taxRate", DisplayName = "Negative tax rate throws")]
    [DataRow(10.00, 1, 1.01, "taxRate", DisplayName = "Tax rate above 1 throws")]
    public void CalculateTotal_WithInvalidInputs_ThrowsArgumentOutOfRangeException(
        double unitPrice, int quantity, double taxRate, string expectedParamName)
    {
        var ex = Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));

        Assert.AreEqual(expectedParamName, ex.ParamName);
    }

    // ───────────────────────────────────────────────
    // ApplyDiscount — DynamicData for complex cases
    // ───────────────────────────────────────────────

    [TestMethod]
    [DynamicData(nameof(ValidDiscountCases), DynamicDataSourceType.Method)]
    public void ApplyDiscount_WithValidInputs_ReturnsDiscountedPrice(
        decimal price, decimal discountPercent, decimal expected, string scenario)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result, $"Failed for: {scenario}");
    }

    private static IEnumerable<object[]> ValidDiscountCases()
    {
        yield return [200.00m, 0m, 200.00m, "No discount"];
        yield return [200.00m, 50m, 100.00m, "50% off"];
        yield return [200.00m, 100m, 0.00m, "100% off (free)"];
        yield return [79.99m, 25m, 59.9925m, "25% off fractional price"];
        yield return [0.00m, 50m, 0.00m, "Zero price with discount"];
        yield return [1000.00m, 10m, 900.00m, "10% off large price"];
        yield return [49.99m, 15.5m, 42.24155m, "Fractional discount percent"];
    }

    [TestMethod]
    [DynamicData(nameof(InvalidDiscountCases), DynamicDataSourceType.Method)]
    public void ApplyDiscount_WithInvalidDiscount_ThrowsArgumentOutOfRangeException(
        decimal price, decimal discountPercent)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(price, discountPercent));
    }

    private static IEnumerable<object[]> InvalidDiscountCases()
    {
        yield return [100.00m, -1m];
        yield return [100.00m, 100.01m];
        yield return [50.00m, 200m];
    }

    // ───────────────────────────────────────────────
    // FormatPrice — DataRow for string output
    // ───────────────────────────────────────────────

    [TestMethod]
    [DataRow(19.99, "$", "$19.99", DisplayName = "Default dollar symbol")]
    [DataRow(19.99, "€", "€19.99", DisplayName = "Euro symbol")]
    [DataRow(0.50, "£", "£0.50", DisplayName = "Sub-unit price with pound")]
    [DataRow(1234.5, "$", "$1234.50", DisplayName = "Trailing zero formatting")]
    public void FormatPrice_WithCurrencySymbol_ReturnsFormattedString(
        double price, string symbol, string expected)
    {
        var result = _calculator.FormatPrice((decimal)price, symbol);

        Assert.AreEqual(expected, result);
    }
}

